def get_daily_message(day_number):
    day_index = ((day_number - 1) % 30) + 1
    return MOTIVATIONAL_MESSAGES.get(day_index, "Dobrej roboty, Szefie!")

import random
def get_bonus_meme():
    return random.choice(BONUS_MEMES)
